const float h2 = h * h;
const float poly6Coeff = poly6;

for (size_t i = start; i < end; ++i) {
    Particle &pi = particles[i];
    glm::ivec3 cell = getCell(&pi, h);

    float density = 0.0f;

    for (int dx = -1; dx <= 1; ++dx) {
        for (int dy = -1; dy <= 1; ++dy) {
            for (int dz = -1; dz <= 1; ++dz) {
                glm::ivec3 neighborCell = cell + glm::ivec3(dx, dy, dz);
                uint32_t hash = getHash(neighborCell);
                uint32_t idx = particleTable[hash];

                while (idx < particleCount && particles[idx].hash == hash) {
                    const Particle &pj = particles[idx];
                    glm::vec3 rVec = pi.position - pj.position;
                    float r2 = glm::dot(rVec, rVec);

                    if (r2 < h2) {
                        density += mass * poly6Coeff * std::pow(h2 - r2, 3.0f);
                    }
                    ++idx;
                }
            }
        }
    }

    density += selfDens;
    pi.density = density;
    pi.pressure = gasConstant * (density - restDensity);
}

